#include <iostream>
#include <vector>

using namespace std;


//templte to accept all types
template <typename funcPointer>

void applyIf(vector<int> &myVector, funcPointer funcIntake ){

    //vector for loop
    for(auto & x : myVector){

        //this take in the struct of FilterAndScale
        funcIntake(x);
    }

}

struct FilterAndScale{
    int threshold;
    double scaleFactor;


    //this is a strucutre constructor, same as class constructors

    FilterAndScale(int thresholdParam, double scaleFactorParam ) : threshold(thresholdParam), scaleFactor(scaleFactorParam) {}

        //this step overloads the () opertor for specific use
      bool operator()(int &numberInput){
        if( numberInput > threshold ){

            //this code runs in () when a struc object is created
            numberInput *= scaleFactor;
            return true;
        }
        else
            return false;

      }

};

int main(){

    vector<int> vec = {1, 3, 5, 34, 46, 100, 3, 8};


    FilterAndScale F_A(5, 10.0);

    //this print the vector values without the changes
    for(auto &v: vec) {
        cout << v << " ";
    }
    cout << "\n";


    //filter and scale is applied here
    applyIf(vec , F_A );


    //this prints the vector values with the values
    for(auto &v : vec) {

        cout << v << " ";

    }

    cout << endl;

}
